<?php
declare(strict_types=1);
function ensure_analytics_schema(): void {static $ready=false;if($ready)return;query("CREATE TABLE IF NOT EXISTS ns_analytics_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event VARCHAR(40) NOT NULL,path VARCHAR(300) NOT NULL,session_hash CHAR(64) NOT NULL,product_id BIGINT UNSIGNED NULL,order_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(event,created_at),INDEX(order_id),FOREIGN KEY(product_id) REFERENCES ns_products(id) ON DELETE SET NULL,FOREIGN KEY(order_id) REFERENCES ns_orders(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$ready=true;}
function analytics_event(string $event,?int $productId=null,?int $orderId=null): void {if(!in_array($event,['landing_view','product_view','add_to_cart','cart_view','checkout_view','payment_started','purchase','order_tracking'],true))return;ensure_analytics_schema();if($orderId&&in_array($event,['payment_started','purchase'],true)&&one('SELECT id FROM ns_analytics_events WHERE event=? AND order_id=? LIMIT 1',[$event,$orderId]))return;$path=mb_substr(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/',0,300);query('INSERT INTO ns_analytics_events(event,path,session_hash,product_id,order_id) VALUES (?,?,?,?,?)',[$event,$path,hash('sha256',session_id()),$productId,$orderId]);}
